#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

// Min reduction over dim=1 of a [B, D1, D2] contiguous float tensor.
// Vectorized-load version: each warp reduces 128 consecutive columns of
// one batch row. Every lane owns 4 consecutive outputs and reads them
// with one aligned 16-byte float4 load per row, plus a second aligned
// float4 (almost always an L1 hit) used to realign the row data when
// the row start is not 16-byte aligned (dim2 not a multiple of 4).
// Split-dim1 version: two warps of the same block cooperate on one
// 128-column chunk, each reducing a strided half of the rows (row
// pairs 4k+2*sub and 4k+2*sub+1). Their partial minima are combined
// through shared memory. This halves the per-warp reduction latency
// and doubles the number of resident blocks, smoothing the tail
// imbalance that limited achieved occupancy on long dim1 reductions.
__global__ void __launch_bounds__(256, 6) min_reduce_dim1_kernel(const float* __restrict__ x,
                                       float* __restrict__ out,
                                       int dim1, int dim2,
                                       long long total) {
    __shared__ float4 red[8][32];
    const int lane = threadIdx.x & 31;
    const int warpId = threadIdx.x >> 5;
    const int sub = warpId & 1;
    const int pairInBlock = warpId >> 1;
    const long long numPairs = ((long long)gridDim.x * blockDim.x) >> 6;
    const long long batch = total / dim2;
    const int chunksPerBatch = (dim2 + 127) >> 7;
    const long long numChunks = batch * (long long)chunksPerBatch;
    const long long totalFloats = total * (long long)dim1;
    const float inf = __int_as_float(0x7f800000);
    const long long pairBase = ((long long)blockIdx.x * blockDim.x) >> 6;
    for (long long wb = pairBase; wb < numChunks; wb += numPairs) {
        const long long w = wb + pairInBlock;
        const bool active = w < numChunks;
        const long long b = active ? (w / chunksPerBatch) : 0;
        const int d0 = active ? ((int)(w - b * (long long)chunksPerBatch) << 7) : 0;
        const long long rowBase = b * (long long)dim1 * dim2;
        int valid = active ? (dim2 - d0) : 0;
        if (valid > 128) valid = 128;
        float4 m0 = make_float4(inf, inf, inf, inf);
        float4 m1 = make_float4(inf, inf, inf, inf);
        if (active) {
            const float* s = x + rowBase + d0 + (long long)(2 * sub) * dim2;
            const bool allSafe =
                (rowBase + (long long)(dim1 - 1) * dim2 + d0 + 132) <= totalFloats;
            if (allSafe) {
                // Unroll the dim1 reduction by two rows and keep two
                // independent accumulator chains so four 16-byte loads can
                // be in flight per iteration, increasing memory-level
                // parallelism. This warp covers row pairs
                // (4k+2*sub, 4k+2*sub+1).
                const long long step4 = 4LL * dim2;
                int i = 2 * sub;
                for (; i + 2 <= dim1; i += 4, s += step4) {
                    const float* s1 = s + dim2;
                    const int off0 = (int)(((size_t)s) >> 2) & 3;
                    const int off1 = (int)(((size_t)s1) >> 2) & 3;
                    const float4* a40 = (const float4*)(s - off0);
                    const float4* a41 = (const float4*)(s1 - off1);
                    const float4 cur0 = __ldcs(a40 + lane);
                    const float4 nxt0 = __ldcs(a40 + lane + 1);
                    const float4 cur1 = __ldcs(a41 + lane);
                    const float4 nxt1 = __ldcs(a41 + lane + 1);
                    float4 r0, r1;
                    switch (off0) {
                        case 0:  r0 = cur0; break;
                        case 1:  r0 = make_float4(cur0.y, cur0.z, cur0.w, nxt0.x); break;
                        case 2:  r0 = make_float4(cur0.z, cur0.w, nxt0.x, nxt0.y); break;
                        default: r0 = make_float4(cur0.w, nxt0.x, nxt0.y, nxt0.z); break;
                    }
                    switch (off1) {
                        case 0:  r1 = cur1; break;
                        case 1:  r1 = make_float4(cur1.y, cur1.z, cur1.w, nxt1.x); break;
                        case 2:  r1 = make_float4(cur1.z, cur1.w, nxt1.x, nxt1.y); break;
                        default: r1 = make_float4(cur1.w, nxt1.x, nxt1.y, nxt1.z); break;
                    }
                    m0.x = fminf(m0.x, r0.x);
                    m0.y = fminf(m0.y, r0.y);
                    m0.z = fminf(m0.z, r0.z);
                    m0.w = fminf(m0.w, r0.w);
                    m1.x = fminf(m1.x, r1.x);
                    m1.y = fminf(m1.y, r1.y);
                    m1.z = fminf(m1.z, r1.z);
                    m1.w = fminf(m1.w, r1.w);
                }
                if (i < dim1) {
                    const int off = (int)(((size_t)s) >> 2) & 3;
                    const float4* a4 = (const float4*)(s - off);
                    const float4 cur = __ldcs(a4 + lane);
                    const float4 nxt = __ldcs(a4 + lane + 1);
                    float4 r;
                    switch (off) {
                        case 0:  r = cur; break;
                        case 1:  r = make_float4(cur.y, cur.z, cur.w, nxt.x); break;
                        case 2:  r = make_float4(cur.z, cur.w, nxt.x, nxt.y); break;
                        default: r = make_float4(cur.w, nxt.x, nxt.y, nxt.z); break;
                    }
                    m0.x = fminf(m0.x, r.x);
                    m0.y = fminf(m0.y, r.y);
                    m0.z = fminf(m0.z, r.z);
                    m0.w = fminf(m0.w, r.w);
                }
            } else {
                const long long step4 = 4LL * dim2;
                for (int i = 2 * sub; i < dim1; i += 4, s += step4) {
                    #pragma unroll
                    for (int rr = 0; rr < 2; ++rr) {
                        const int ri = i + rr;
                        if (ri >= dim1) break;
                        const float* sr = s + (long long)rr * dim2;
                        if (rowBase + (long long)ri * dim2 + d0 + 132 <= totalFloats) {
                            const int off = (int)(((size_t)sr) >> 2) & 3;
                            const float4* a4 = (const float4*)(sr - off);
                            const float4 cur = __ldcs(a4 + lane);
                            const float4 nxt = __ldcs(a4 + lane + 1);
                            float4 r;
                            switch (off) {
                                case 0:  r = cur; break;
                                case 1:  r = make_float4(cur.y, cur.z, cur.w, nxt.x); break;
                                case 2:  r = make_float4(cur.z, cur.w, nxt.x, nxt.y); break;
                                default: r = make_float4(cur.w, nxt.x, nxt.y, nxt.z); break;
                            }
                            m0.x = fminf(m0.x, r.x);
                            m0.y = fminf(m0.y, r.y);
                            m0.z = fminf(m0.z, r.z);
                            m0.w = fminf(m0.w, r.w);
                        } else {
                            #pragma unroll
                            for (int j = 0; j < 4; ++j) {
                                const int dd = 4 * lane + j;
                                if (dd < valid) {
                                    const float v = __ldcs(sr + dd);
                                    if (j == 0)      m0.x = fminf(m0.x, v);
                                    else if (j == 1) m0.y = fminf(m0.y, v);
                                    else if (j == 2) m0.z = fminf(m0.z, v);
                                    else             m0.w = fminf(m0.w, v);
                                }
                            }
                        }
                    }
                }
            }
            m0.x = fminf(m0.x, m1.x);
            m0.y = fminf(m0.y, m1.y);
            m0.z = fminf(m0.z, m1.z);
            m0.w = fminf(m0.w, m1.w);
        }
        red[warpId][lane] = m0;
        __syncthreads();
        if (active && sub == 0) {
            const float4 o = red[warpId + 1][lane];
            m0.x = fminf(m0.x, o.x);
            m0.y = fminf(m0.y, o.y);
            m0.z = fminf(m0.z, o.z);
            m0.w = fminf(m0.w, o.w);
            float* ob = out + b * (long long)dim2 + d0;
            #pragma unroll
            for (int j = 0; j < 4; ++j) {
                const int dd = 4 * lane + j;
                if (dd < valid) {
                    ob[dd] = (j == 0) ? m0.x : (j == 1) ? m0.y : (j == 2) ? m0.z : m0.w;
                }
            }
        }
        __syncthreads();
    }
