    long long chunksPerBatch = (dim2 + 127) / 128;
    long long blocks = (batch * chunksPerBatch * 64 + threads - 1) / threads;
    if (blocks > 65535) blocks = 65535;

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    min_reduce_dim1_kernel<<<(int)blocks, threads, 0, stream>>>(
        xc.data_ptr<float>(), out.data_ptr<float>(),
        (int)dim1, (int)dim2, total);
    return out;
